	@Test
	void earlyCloseDisposesCursorBeforeNextLookup(@TempDir File directory) throws Exception {
		try (Fixture fixture = new Fixture(directory);
				SailDataset dataset = fixture.dataset();
				var first = dataset.getStatements(node(0), BRANCH, null, GRAPH)) {
			assertTrue(first.hasNext());
			first.next();
			assertEquals(1, fixture.cursors.size(), "The first statement scan must allocate one retained cursor");
			LmdbRecordIterator cursor = fixture.cursors.getFirst();
			long firstGeneration = cursor.cancellationGeneration();
			first.close();
			verify(cursor, times(1)).dispose();
			try (var next = dataset.getStatements(node(7), PREDICATE, null, GRAPH)) {
				assertEquals(2, fixture.cursors.size(), "An early-closed cursor must not be borrowed again");
				assertFalse(cursor.requestCancellation(firstGeneration),
						"A delayed cancellation of a disposed cursor must be harmless");
				assertFalse(CooperativeCancellation.forward(first));
				first.close();
				assertSingle(next, node(7), node(8));
			}
			verify(cursor, times(1)).dispose();
		}
	}

