	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void idleCursorRejectsInvalidationAndClosesBesideAFreshSnapshot(boolean retireView, @TempDir File directory)
			throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			LmdbSailStore backing = fixture.store.getBackingStore();
			SailDataset dataset;
			LmdbSailStore.ReadView view;
			try (var admission = backing.beginDatasetAdmission(IsolationLevels.SNAPSHOT_READ, null)) {
				view = admission.view();
				dataset = fixture.dataset();
			}
			try (dataset) {
				try (var rows = dataset.getStatements(node(1), PREDICATE, null, GRAPH)) {
					assertSingle(rows, node(1), node(2));
				}
				assertEquals(1, fixture.cursors.size(), "Invalidation must find a retained cursor idle in its dataset");
				LmdbRecordIterator cursor = fixture.cursors.getFirst();
				if (retireView) {
					// Replay retirement can return the native transaction before the dataset itself closes.
					view.retireNativeSnapshots(LmdbSailStore.MapResizeKind.TRIPLE_STORE);
				} else {
					// These are the transaction transitions used around a memory-map resize.
					fixture.triples.getTxnManager().deactivate();
					fixture.triples.getTxnManager().activate();
				}
				SailException failure = assertThrows(SailException.class, () -> {
					try (var rows = dataset.getStatements(node(3), PREDICATE, null, GRAPH)) {
						rows.hasNext();
					}
				});
				assertTrue(failure.getMessage().contains("SNAPSHOT"));
				verify(fixture.triples, times(0)).resetTriples(eq(cursor), anyLong(), anyLong(), anyLong(),
						anyLong(), anyBoolean());

				try (SailDataset fresh = fixture.dataset();
						var rows = fresh.getStatements(node(5), PREDICATE, null, GRAPH)) {
					assertTrue(rows.hasNext());
					assertEquals(2, fixture.cursors.size(), "A replacement snapshot must allocate its own cursor");
					dataset.close();
					verify(cursor, times(1)).dispose();
					assertSingle(rows, node(5), node(6));
				}
			}
			verify(fixture.cursors.getFirst(), times(1)).dispose();
		}
	}

	private static void assertSingle(CloseableIteration<? extends Statement> rows, IRI subject, IRI object) {
		assertTrue(rows.hasNext());
		Statement row = rows.next();
		assertEquals(subject, row.getSubject());
		assertEquals(PREDICATE, row.getPredicate());
		assertEquals(object, row.getObject());
		assertEquals(GRAPH, row.getContext());
		assertFalse(rows.hasNext());
	}

	private static IRI node(int index) {
		return Values.iri("urn:cursor-reuse:node:" + index);
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false)
				.setAsyncValueCleanup(false);
	}

	private enum Direction {
		FORWARD,
		REVERSE
	}

	private static final class Fixture implements AutoCloseable {
		private final List<LmdbRecordIterator> cursors = new ArrayList<>();
		private final AtomicBoolean interruptReset = new AtomicBoolean();
		private final AtomicReference<RuntimeException> resetFailure = new AtomicReference<>();
		private final AtomicReference<RuntimeException> wrapperConstructionFailure = new AtomicReference<>();
		private final LmdbStore store;
		private final TripleStore triples;

		private Fixture(File directory) throws IOException {
			// Seed without instrumentation. The measured fixture then opens an ordinary, read-only store view.
			LmdbStore writer = new LmdbStore(directory, config());
			writer.init();
			try (LmdbStoreConnection connection = (LmdbStoreConnection) writer.getConnection()) {
				connection.begin();
				for (int i = 0; i < EDGES; i++) {
					connection.addStatement(node(i), PREDICATE, node(i + 1), GRAPH);
				}
				connection.addStatement(node(0), BRANCH, node(2), GRAPH);
				connection.addStatement(node(0), BRANCH, node(4), GRAPH);
				connection.commit();
			} finally {
				writer.shutDown();
			}
			store = new LmdbStore(directory, config()) {
				@Override
				LmdbSailStore createBackingStore(File dataDir, StoreProperties properties, LmdbStoreConfig config,
						boolean sketchBasedJoinEstimatorEnabled) throws IOException {
					return new LmdbSailStore(dataDir, properties, config, sketchBasedJoinEstimatorEnabled,
							ValueStore::new, (tripleDir, tripleProperties, tripleConfig,
									values) -> observed(
											new TripleStore(tripleDir, tripleProperties, tripleConfig, values)));
				}
			};
			try {
				store.init();
				triples = store.getBackingStore().getTripleStore();
				assertSame(TripleStore.class, triples.getClass(),
						"Inline observation must preserve exact-class eligibility and real index behavior");
				cursors.clear();
				clearInvocations(triples);
			} catch (RuntimeException | Error failure) {
				try {
					store.shutDown();
				} catch (RuntimeException | Error cleanup) {
					failure.addSuppressed(cleanup);
				}
				throw failure;
			}
		}

		private TripleStore observed(TripleStore real) {
			// Install interception before startup callbacks can use the store. No live mock is left between
			// doAnswer()/when(): a concurrent background call could otherwise consume unfinished stubbing.
			return mock(TripleStore.class, withSettings().spiedInstance(real).defaultAnswer(invocation -> {
				String method = invocation.getMethod().getName();
				if (method.equals("resetTriples")) {
					RuntimeException failure = resetFailure.get();
					if (failure != null) {
						throw failure;
					}
				}
				Object result = invocation.callRealMethod();
				if (method.equals("getTriplesRetained") && invocation.getArguments().length == 7) {
					LmdbRecordIterator cursor = mock(LmdbRecordIterator.class,
							withSettings().spiedInstance(result).defaultAnswer(cursorInvocation -> {
								if (cursorInvocation.getMethod().getName().equals("reset")
										&& interruptReset.getAndSet(false)) {
									// Reproduce a writer's provisional stamp after withGeneration acquired the outer
									// reader. Drive the real nested readLock() interruption, not a mocked reset error.
									var field = StampedLongAdderLockManager.class.getDeclaredField("stampedLock");
									field.setAccessible(true);
									var lock = (StampedLock) field.get(((LmdbRecordIterator) result).transaction()
											.lockManager());
									long write = lock.writeLock();
									Thread.currentThread().interrupt();
									try {
										return cursorInvocation.callRealMethod();
									} finally {
										lock.unlockWrite(write);
									}
								}
								if (cursorInvocation.getMethod().getName().equals("cancellationGeneration")) {
									RuntimeException failure = wrapperConstructionFailure.getAndSet(null);
									if (failure != null) {
										throw failure;
									}
								}
								return cursorInvocation.callRealMethod();
							}));
					cursors.add(cursor);
					return cursor;
				}
				return result;
			}));
		}

		private SailDataset dataset() {
			return store.getBackingStore().getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT_READ);
		}

		@Override
		public void close() {
			store.shutDown();
		}
	}
